// 04 Parse + validate
// Required keys, confidence 0-1, known category.
const raw = $input.first().json;
const fields = $('02 Set fields').first().json;

let modelText = '';
try {
  modelText = raw.choices[0].message.content;
} catch (e) {
  throw new Error('Unexpected API response shape - no choices[0].message.content found');
}

let parsed;
try {
  parsed = JSON.parse(modelText);
} catch (e) {
  throw new Error('Model did not return valid JSON: ' + modelText);
}

const requiredKeys = ['category', 'confidence', 'summary', 'risk', 'needs_human'];
for (const key of requiredKeys) {
  if (!(key in parsed)) {
    throw new Error('Missing required key: ' + key);
  }
}

const allowedCategories = ['billing', 'technical', 'account', 'spam', 'other'];
const allowedRisk = ['low', 'medium', 'high'];

if (!allowedCategories.includes(parsed.category)) {
  throw new Error('category not in allowed list: ' + parsed.category);
}
if (typeof parsed.confidence !== 'number' || parsed.confidence < 0 || parsed.confidence > 1) {
  throw new Error('confidence out of range or missing: ' + parsed.confidence);
}
if (!parsed.summary || typeof parsed.summary !== 'string' || parsed.summary.length === 0) {
  throw new Error('summary missing or empty');
}
if (!allowedRisk.includes(parsed.risk)) {
  throw new Error('risk not in allowed list: ' + parsed.risk);
}

// Safety override: high risk always forces human review, regardless of model output
if (parsed.risk === 'high') {
  parsed.needs_human = true;
}
// Low confidence also forces human review
if (parsed.confidence < 0.6) {
  parsed.needs_human = true;
}

return [{
  json: {
    request_id: fields.request_id,
    message: fields.message,
    received_at: fields.received_at,
    category: parsed.category,
    confidence: parsed.confidence,
    summary: parsed.summary,
    risk: parsed.risk,
    needs_human: parsed.needs_human,
    validation_status: 'valid'
  }
}];
